<?php require_once __DIR__.'/../../includes/auth.php';requireSuperAdmin();require_once __DIR__.'/../../includes/functions.php';$rows=$pdo->query("SELECT t.*,e.name event_name,x.full_name contestant_name,CASE WHEN v.id IS NULL THEN 0 ELSE v.vote_count END recorded_votes FROM transactions t JOIN events e ON e.id=t.event_id JOIN contestants x ON x.id=t.contestant_id LEFT JOIN votes v ON v.transaction_id=t.id ORDER BY t.id DESC LIMIT 300")->fetchAll();$success=$pending=$failed=$orphan=0;$revenue=0;foreach($rows as $r){if($r['status']==='Successful'){$success++;$revenue+=(float)$r['amount'];if((int)$r['recorded_votes']!==(int)$r['vote_count'])$orphan++;}elseif($r['status']==='Pending')$pending++;else $failed++;}$pageTitle='Reconciliation';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/sidebar.php';?><main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><div class="mb-4"><span class="section-kicker">FINANCE</span><h1 class="page-title">Payment & Vote Reconciliation</h1><p class="page-subtitle">Every successful transaction should have exactly one vote record.</p></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card-box stat"><div class="stat-label">Successful</div><div class="stat-value"><?=$success?></div></div></div><div class="col-md-3"><div class="card-box stat"><div class="stat-label">Pending</div><div class="stat-value"><?=$pending?></div></div></div><div class="col-md-3"><div class="card-box stat"><div class="stat-label">Failed/Cancelled</div><div class="stat-value"><?=$failed?></div></div></div><div class="col-md-3"><div class="card-box stat"><div class="stat-label">Mismatch</div><div class="stat-value"><?=$orphan?></div></div></div></div><div class="panel"><div class="panel-head"><h5>Recent Transactions</h5><strong>GHS <?=number_format($revenue,2)?></strong></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Reference</th><th>Event</th><th>Contestant</th><th>Amount</th><th>Votes</th><th>Recorded</th><th>Status</th><th>Payment Ref</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="font-monospace small"><?=e($r['transaction_reference'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['contestant_name'])?></td><td>GHS <?=number_format((float)$r['amount'],2)?></td><td><?=$r['vote_count']?></td><td><?=$r['recorded_votes']?></td><td><?=e($r['status'])?></td><td class="font-monospace small"><?=e($r['payment_reference']??'')?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="text-center py-5 text-muted">No transactions yet.</td></tr><?php endif;?></tbody></table></div></div></section></main><?php require __DIR__.'/../../includes/footer.php';?>
